def build_component_tree(grid, cell_value=8, start_cell=None):
    """Build a tree representation of the connected component"""
    rows, cols = len(grid), len(grid[0])
    children = defaultdict(list)

    # Find root if not specified (top-leftmost)
    if start_cell is None:
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == cell_value:
                    start_cell = (r, c)
                    break
            if start_cell:
                break

    # BFS from root to build parent-child relationships
    visited = set()
    queue = deque([start_cell])
    visited.add(start_cell)

    while queue:
        curr = queue.popleft()
        curr_r, curr_c = curr

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = curr_r + dr, curr_c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == cell_value:
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    children[curr].append((nr, nc))
                    queue.append((nr, nc))

    return children

